from fastapi import FastAPI, HTTPException, status
import logging

app = FastAPI()
DB = {}

@app.get("/v1/cuentas/{cuenta_id}/movimientos")
def movimientos(cuenta_id: str, usuario: dict = None):
    if not usuario or usuario.get("cuenta_id") != cuenta_id:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="No autorizado para acceder a esta cuenta")

    try:
        if cuenta_id not in DB:
            raise KeyError("Cuenta no encontrada")
        return DB[cuenta_id]["movimientos"]
    except KeyError as e:
        logging.error(f"Error de acceso a datos: {e}")
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Cuenta no encontrada")
    except Exception as e:
        logging.error(f"Error inesperado: {e}")
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Error interno del servidor")

